 if(role==='commander_support'&&(/(?:gains?|has) haste|untap target (?:creature|permanent)|untap another target|untap an? [^.]* you control|(?:target|another) (?:creature|permanent)[^.]{0,80}(?:hexproof|indestructible)|(?:creatures|permanents) you control (?:gain|have) (?:hexproof|indestructible)/.test(rules)))score=30;
